using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_fea0b8704dcc426680e62b14abcb1b30.Client.Auth;

/// <summary>
/// Client-side (WebAssembly) AuthenticationStateProvider that restores
/// auth state from PersistentComponentState, which was serialized by the server
/// during prerendering. This ensures the user's identity survives the
/// Server → WebAssembly handoff.
/// </summary>
public sealed class ClientAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly AuthenticationState UnauthenticatedState =
        new(new ClaimsPrincipal(new ClaimsIdentity()));

    private readonly Task<AuthenticationState> _authStateTask;

    public ClientAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo)
            && userInfo is not null)
        {
            _authStateTask = Task.FromResult(BuildAuthState(userInfo));
        }
        else
        {
            _authStateTask = Task.FromResult(UnauthenticatedState);
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authStateTask;

    private static AuthenticationState BuildAuthState(UserInfo userInfo)
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, userInfo.Email),
            new(ClaimTypes.Email, userInfo.Email)
        };

        foreach (var role in userInfo.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        return new AuthenticationState(new ClaimsPrincipal(identity));
    }
}

